SELECT ?zone ?point ?tsid WHERE {
  ?zone brick:hasSubComponent ?point .
  ?point ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?tsid .
  FILTER(str(?zone) LIKE "%Perimeter_ZN_1%" || str(?zone) LIKE "%Perimeter_ZN_2%")
}

